// ── Bybit V5 HMAC-SHA256 signature (GET) ──────────────────────
const crypto = require('node:crypto');
const symbol       = $input.first().json.symbol;
const interval     = $input.first().json.klineInterval;
const limit        = $input.first().json.klineLimit;
const apiKey       = $env.BYBIT_API_KEY;
const apiSecret    = $env.BYBIT_API_SECRET;
const timestamp    = Date.now().toString();
const recvWindow   = '5000';
const queryString  = `symbol=${symbol}&interval=${interval}&limit=${limit}`;
const paramStr     = timestamp + apiKey + recvWindow + queryString;
const signature    = crypto.createHmac('sha256', apiSecret).update(paramStr).digest('hex');

return [{
  json: {
    ...($input.first().json),
    kline: { apiKey, timestamp, recvWindow, signature, queryString }
  }
}];

// ── Sign Bybit orderbook GET request ──────────────────────────
const crypto = require('node:crypto');
const prev         = $('Init Config').first().json;
const symbol       = prev.symbol;
const apiKey       = $env.BYBIT_API_KEY;
const apiSecret    = $env.BYBIT_API_SECRET;
const timestamp    = Date.now().toString();
const recvWindow   = '5000';
const queryString  = `symbol=${symbol}&limit=25`;
const paramStr     = timestamp + apiKey + recvWindow + queryString;
const signature    = crypto.createHmac('sha256', apiSecret).update(paramStr).digest('hex');

return [{
  json: { symbol, apiKey, timestamp, recvWindow, signature, queryString, bybitBase: prev.bybitBase }
}];

// ── Compute RSI-14, EMA-20/50/200, MACD-12/26/9 ──────────────
const klineRaw = $('Bybit: Fetch Klines').first().json;
const obRaw    = $('Bybit: Fetch OrderBook').first().json;
const config   = $('Init Config').first().json;

// Bybit kline format: [startTime, open, high, low, close, volume, turnover]
// API returns newest-first → reverse for chronological order
const rawList = klineRaw.result?.list || [];
const ohlcv = rawList.map(c => ({
  time:   parseInt(c[0]),
  open:   parseFloat(c[1]),
  high:   parseFloat(c[2]),
  low:    parseFloat(c[3]),
  close:  parseFloat(c[4]),
  volume: parseFloat(c[5])
})).reverse();

if (ohlcv.length < 30) {
  throw new Error(`Insufficient kline data: ${ohlcv.length} candles`);
}

const closes  = ohlcv.map(c => c.close);
const highs   = ohlcv.map(c => c.high);
const lows    = ohlcv.map(c => c.low);
const volumes = ohlcv.map(c => c.volume);

// ── EMA ────────────────────────────────────────────────────────
function ema(prices, period) {
  if (prices.length < period) return null;
  const k = 2 / (period + 1);
  let val = prices.slice(0, period).reduce((a, b) => a + b, 0) / period;
  for (let i = period; i < prices.length; i++) {
    val = prices[i] * k + val * (1 - k);
  }
  return Math.round(val * 100) / 100;
}

// ── RSI ────────────────────────────────────────────────────────
function rsi(prices, period = 14) {
  if (prices.length < period + 1) return null;
  let gains = 0, losses = 0;
  for (let i = 1; i <= period; i++) {
    const d = prices[i] - prices[i - 1];
    if (d > 0) gains += d; else losses -= d;
  }
  let ag = gains / period, al = losses / period;
  for (let i = period + 1; i < prices.length; i++) {
    const d = prices[i] - prices[i - 1];
    ag = (ag * (period - 1) + Math.max(0, d)) / period;
    al = (al * (period - 1) + Math.max(0, -d)) / period;
  }
  if (al === 0) return 100;
  return Math.round((100 - 100 / (1 + ag / al)) * 100) / 100;
}

// ── MACD ───────────────────────────────────────────────────────
function macdFull(prices) {
  if (prices.length < 35) return null;
  // Build MACD line history to compute signal line
  const k12 = 2 / (12 + 1), k26 = 2 / (26 + 1), k9 = 2 / (9 + 1);
  let e12 = prices.slice(0, 12).reduce((a, b) => a + b, 0) / 12;
  let e26 = prices.slice(0, 26).reduce((a, b) => a + b, 0) / 26;
  const macdLine = [];
  for (let i = 12; i < prices.length; i++) {
    e12 = prices[i] * k12 + e12 * (1 - k12);
    if (i >= 25) {
      e26 = prices[i] * k26 + e26 * (1 - k26);
      macdLine.push(e12 - e26);
    }
  }
  if (macdLine.length < 9) return null;
  let signal = macdLine.slice(0, 9).reduce((a, b) => a + b, 0) / 9;
  for (let i = 9; i < macdLine.length; i++) {
    signal = macdLine[i] * k9 + signal * (1 - k9);
  }
  const last = macdLine[macdLine.length - 1];
  return {
    macd:      Math.round(last * 100) / 100,
    signal:    Math.round(signal * 100) / 100,
    histogram: Math.round((last - signal) * 100) / 100
  };
}

// ── Candlestick pattern detection ──────────────────────────────
function detectPattern(ohlcv) {
  const n = ohlcv.length;
  const c = ohlcv[n - 1], p = ohlcv[n - 2], pp = ohlcv[n - 3];
  const body    = c => Math.abs(c.close - c.open);
  const isGreen = c => c.close > c.open;
  const range   = c => c.high - c.low;

  // Doji
  if (body(c) / range(c) < 0.1) return 'DOJI';
  // Hammer (bullish reversal)
  if (isGreen(c) && (c.low < c.open) && (c.open - c.low) > 2 * body(c)) return 'HAMMER';
  // Shooting star (bearish reversal)
  if (!isGreen(c) && (c.high - c.open) > 2 * body(c)) return 'SHOOTING_STAR';
  // Bullish engulfing
  if (isGreen(c) && !isGreen(p) && c.open < p.close && c.close > p.open) return 'BULLISH_ENGULFING';
  // Bearish engulfing
  if (!isGreen(c) && isGreen(p) && c.open > p.close && c.close < p.open) return 'BEARISH_ENGULFING';
  // Morning star
  if (isGreen(c) && !isGreen(pp) && body(p) < body(pp) * 0.3 && c.close > (pp.open + pp.close) / 2) return 'MORNING_STAR';
  // Evening star
  if (!isGreen(c) && isGreen(pp) && body(p) < body(pp) * 0.3 && c.close < (pp.open + pp.close) / 2) return 'EVENING_STAR';
  return 'NONE';
}

// ── Orderbook pressure ─────────────────────────────────────────
const ob = obRaw.result || {};
const bids = (ob.b || []).slice(0, 5).map(b => parseFloat(b[0]) * parseFloat(b[1]));
const asks = (ob.a || []).slice(0, 5).map(a => parseFloat(a[0]) * parseFloat(a[1]));
const bidVol = bids.reduce((a, b) => a + b, 0);
const askVol = asks.reduce((a, b) => a + b, 0);
const obPressure = bidVol / (bidVol + askVol); // > 0.5 = bullish

const last  = ohlcv[ohlcv.length - 1];
const prev  = ohlcv[ohlcv.length - 2];
const ema20 = ema(closes, 20);
const ema50 = ema(closes, 50);
const ema200 = ema(closes, 200);
const rsi14 = rsi(closes, 14);
const macdData = macdFull(closes);
const pattern = detectPattern(ohlcv);
const vol20avg = volumes.slice(-20).reduce((a, b) => a + b, 0) / 20;
const volRatio = last.volume / vol20avg;

return [{
  json: {
    symbol:       config.symbol,
    currentPrice: last.close,
    prevClose:    prev.close,
    priceChangePct: Math.round(((last.close - prev.close) / prev.close) * 10000) / 100,
    rsi:          rsi14,
    ema20,
    ema50,
    ema200,
    macd:         macdData,
    pattern,
    obPressure:   Math.round(obPressure * 1000) / 1000,
    volRatio:     Math.round(volRatio * 100) / 100,
    trend:        last.close > ema200 ? 'UPTREND' : 'DOWNTREND',
    ema_alignment: ema20 > ema50 && ema50 > ema200 ? 'BULLISH' : ema20 < ema50 && ema50 < ema200 ? 'BEARISH' : 'MIXED',
    candleCount:  ohlcv.length,
    liveTrading:  config.liveTrading,
    minConfidence: parseFloat(config.minConfidence),
    maxRiskPct:   parseFloat(config.maxRiskPct)
  }
}];

// ── Parse CryptoPanic response ────────────────────────────────
const raw = $input.first().json;
const taData = $('Compute: TA Indicators').first().json;

const results = raw.results || [];
const news = results.slice(0, 8).map(n => ({
  title:     n.title,
  published: n.published_at,
  source:    n.source?.title || 'Unknown',
  domain:    n.source?.domain || '',
  url:       n.url,
  votes_positive: n.votes?.positive || 0,
  votes_negative: n.votes?.negative || 0,
  currencies: (n.currencies || []).map(c => c.code).join(', ')
}));

return [{
  json: {
    ...taData,
    news,
    newsCount: news.length,
    newsFetchedAt: new Date().toISOString()
  }
}];

