// ── Parse TA/Trader AI response ───────────────────────────────
const raw  = $input.first().json;
const prev = $('Parse: Sentiment').first().json;

let signal = {};
try {
  const content = raw.choices?.[0]?.message?.content || '{}';
  signal        = JSON.parse(content);
} catch (e) {
  signal        = { side: 'HOLD', confidence: 0, reasoning: 'Parse error' };
}

// Validate prices are reasonable (within 10% of current price)
const price = prev.currentPrice;
const isValidPrice = (p) => p && p > price * 0.85 && p < price * 1.15;

const entryPrice = isValidPrice(signal.entryPrice) ? signal.entryPrice : price;
const tpPrice    = signal.side === 'BUY'
  ? (signal.tpPrice   > entryPrice ? signal.tpPrice   : entryPrice * 1.02)
  : (signal.tpPrice   < entryPrice ? signal.tpPrice   : entryPrice * 0.98);
const slPrice    = signal.side === 'BUY'
  ? (signal.slPrice   < entryPrice ? signal.slPrice   : entryPrice * 0.99)
  : (signal.slPrice   > entryPrice ? signal.slPrice   : entryPrice * 1.01);

return [{
  json: {
    ...prev,
    taSignal: {
      side:           signal.side           || 'HOLD',
      confidence:     signal.confidence     || 0,
      entryPrice:     Math.round(entryPrice * 100) / 100,
      tpPrice:        Math.round(tpPrice    * 100) / 100,
      slPrice:        Math.round(slPrice    * 100) / 100,
      tp2Price:       signal.tp2Price       || null,
      riskRewardRatio: signal.riskRewardRatio || 1,
      reasoning:      signal.reasoning      || '',
      keyFactors:     signal.keyFactors     || [],
      timeframe:      signal.timeframe      || 'SHORT'
    }
  }
}];

// ── Sign Bybit wallet balance GET request ────────────────────
const crypto     = require('node:crypto');
const apiKey     = $env.BYBIT_API_KEY;
const apiSecret  = $env.BYBIT_API_SECRET;
const bybitBase  = $('Init Config').first().json.bybitBase;
const timestamp  = Date.now().toString();
const recvWindow = '5000';
const qs         = 'accountType=UNIFIED';
const paramStr   = timestamp + apiKey + recvWindow + qs;
const signature  = crypto.createHmac('sha256', apiSecret).update(paramStr).digest('hex');
const prev       = $input.first().json;

return [{
  json: {
    ...prev,
    balanceReq: { apiKey, timestamp, recvWindow, signature, qs, bybitBase }
  }
}];

// ── Kelly Criterion + Position Sizing ────────────────────────
const balanceRaw = $input.first().json;
const prev       = $('Parse: TA Signal').first().json;
const signal     = prev.taSignal;

// Extract equity from Bybit UNIFIED account
const accountList = balanceRaw.result?.list || [];
const account     = accountList.find(a => a.accountType === 'UNIFIED') || accountList[0] || {};
const equity      = parseFloat(account.totalEquity || account.totalWalletBalance || '1000');
const availableBalance = parseFloat(account.totalAvailableBalance || equity * 0.8);

const maxRiskPct  = prev.maxRiskPct || 0.005;
const maxLeverage = parseFloat($env.MAX_LEVERAGE || '3');
const confidence  = signal.confidence;
const entryPrice  = signal.entryPrice;
const tpPrice     = signal.tpPrice;
const slPrice     = signal.slPrice;

if (!entryPrice || !tpPrice || !slPrice || signal.side === 'HOLD') {
  return [{
    json: {
      ...prev,
      position: null,
      skipReason: `HOLD signal or missing price levels`,
      equity,
      availableBalance
    }
  }];
}

const reward = Math.abs(tpPrice - entryPrice);
const risk   = Math.abs(entryPrice - slPrice);
if (risk === 0) {
  return [{ json: { ...prev, position: null, skipReason: 'SL equals entry', equity } }];
}

const rr = reward / risk;
// Kelly: f* = (b*p - q) / b
const p  = Math.max(0.4, Math.min(0.9, confidence));
const q  = 1 - p;
const kellyFull = (rr * p - q) / rr;
const halfKelly = Math.max(0, kellyFull * 0.5); // half-Kelly for safety

// Risk in USD: minimum of maxRisk% and half-Kelly%
const riskPct    = Math.min(maxRiskPct, halfKelly);
const riskUSD    = equity * riskPct;

// Position size: riskUSD / (entry - SL) = qty in base asset
const qtyRaw     = riskUSD / risk;
const qty        = Math.floor(qtyRaw * 1000) / 1000; // round down to 3dp

// Leverage: notional / margin
const notional   = qty * entryPrice;
const leverage   = Math.min(maxLeverage, Math.ceil(notional / (riskUSD * 10)));

return [{
  json: {
    ...prev,
    equity,
    availableBalance,
    position: {
      qty,
      leverage,
      notional:      Math.round(notional * 100) / 100,
      riskUSD:       Math.round(riskUSD  * 100) / 100,
      riskPct:       Math.round(riskPct  * 10000) / 100,
      kellyFull:     Math.round(kellyFull * 10000) / 10000,
      halfKelly:     Math.round(halfKelly * 10000) / 10000,
      riskReward:    Math.round(rr * 100) / 100
    }
  }
}];

