// ── Parse Risk AI response ─────────────────────────────────────
const raw  = $input.first().json;
const prev = $('Compute: Kelly Position Size').first().json;

let risk = {};
try {
  const content = raw.choices?.[0]?.message?.content || '{}';
  risk          = JSON.parse(content);
} catch (e) {
  risk          = { approved: false, reason: 'Risk AI parse error', risk_score: 10, warnings: [] };
}

// Use adjusted values if provided, else keep original
const pos       = prev.position || {};
const finalQty  = risk.adjusted_qty       || pos.qty       || 0;
const finalLevg = risk.adjusted_leverage  || pos.leverage  || 1;

// Additional hard guards
const minConf = prev.minConfidence || 0.6;
const approved = risk.approved === true
  && prev.taSignal.side !== 'HOLD'
  && prev.taSignal.confidence >= minConf
  && prev.position !== null
  && finalQty > 0;

return [{
  json: {
    ...prev,
    riskDecision: {
      approved,
      reason:          risk.reason   || '',
      riskScore:       risk.risk_score || 5,
      warnings:        risk.warnings  || [],
      finalQty,
      finalLeverage:   finalLevg,
      simulationMode: prev.liveTrading !== true
    }
  }
}];

// ── Sign Bybit POST order request ─────────────────────────────
const crypto     = require('node:crypto');
const prev       = $input.first().json;
const signal     = prev.taSignal;
const risk       = prev.riskDecision;
const apiKey     = $env.BYBIT_API_KEY;
const apiSecret  = $env.BYBIT_API_SECRET;
const bybitBase  = $('Init Config').first().json.bybitBase;
const timestamp  = Date.now().toString();
const recvWindow = '5000';

// If simulation mode, skip real order
if (risk.simulationMode) {
  return [{
    json: {
      ...prev,
      orderPayload: null,
      simulatedOrder: {
        symbol:      prev.symbol,
        side:        signal.side,
        orderType:   'Market',
        qty:         risk.finalQty.toString(),
        leverage:    risk.finalLeverage,
        entryPrice:  signal.entryPrice,
        tpPrice:     signal.tpPrice,
        slPrice:     signal.slPrice,
        simulated:   true,
        timestamp:   new Date().toISOString()
      }
    }
  }];
}

// Set leverage (category: linear for USDT perpetual)
const orderBody = {
  category:    'linear',
  symbol:      prev.symbol,
  side:        signal.side === 'BUY' ? 'Buy' : 'Sell',
  orderType:   'Market',
  qty:         risk.finalQty.toString(),
  timeInForce: 'GoodTillCancel',
  positionIdx: 0
};

const bodyStr   = JSON.stringify(orderBody);
const paramStr  = timestamp + apiKey + recvWindow + bodyStr;
const signature = crypto.createHmac('sha256', apiSecret).update(paramStr).digest('hex');

return [{
  json: {
    ...prev,
    orderPayload:  orderBody,
    orderSign: { apiKey, timestamp, recvWindow, signature, bybitBase }
  }
}];

// ── Sign & build TP/SL order ──────────────────────────────────
const crypto       = require('node:crypto');
const raw          = $input.first().json;
const prev         = $('Sign: Place Order').first().json;
const signal       = prev.taSignal;
const risk         = prev.riskDecision;

// If simulated, skip
if (risk.simulationMode) {
  return [{ json: { ...prev, orderResult: raw, tpSlSkipped: true } }];
}

const orderId = raw.result?.orderId;
if (!orderId) {
  return [{ json: { ...prev, orderResult: raw, tpSlSkipped: true, error: 'No orderId returned' } }];
}

const apiKey     = $env.BYBIT_API_KEY;
const apiSecret  = $env.BYBIT_API_SECRET;
const bybitBase  = $('Init Config').first().json.bybitBase;
const timestamp  = Date.now().toString();
const recvWindow = '5000';

const tpSlBody = {
  category:   'linear',
  symbol:     prev.symbol,
  orderId,
  takeProfit: signal.tpPrice.toString(),
  stopLoss:   signal.slPrice.toString(),
  tpTriggerBy: 'MarkPrice',
  slTriggerBy: 'MarkPrice'
};

const bodyStr   = JSON.stringify(tpSlBody);
const paramStr  = timestamp + apiKey + recvWindow + bodyStr;
const signature = crypto.createHmac('sha256', apiSecret).update(paramStr).digest('hex');

return [{
  json: {
    ...prev,
    orderResult:  raw,
    orderId,
    tpSlPayload:  tpSlBody,
    tpSlSign: { apiKey, timestamp, recvWindow, signature, bybitBase }
  }
}];

// ── Build rejection log entry ──────────────────────────────────
const prev = $input.first().json;
return [{
  json: {
    ...prev,
    rejectionLog: {
      symbol:     prev.symbol,
      side:       prev.taSignal?.side || 'HOLD',
      reason:     prev.riskDecision?.reason || prev.skipReason || 'Unknown',
      confidence: prev.taSignal?.confidence || 0,
      riskScore:  prev.riskDecision?.riskScore || 0,
      warnings:   prev.riskDecision?.warnings || [],
      timestamp:  new Date().toISOString()
    }
  }
}];

// ── Format Telegram notification ─────────────────────────────
const d   = $input.first().json;
const sig = d.taSignal || {};
const rm  = d.riskDecision || {};
const pos = d.position || {};
const icon = rm.approved ? (sig.side === 'BUY' ? '🟢' : '🔴') : '⚪';
const status = rm.approved
  ? (rm.simulationMode ? '📊 SIMULATED' : '✅ LIVE ORDER')
  : '🚫 REJECTED';

const lines = [
  `${icon} *${d.symbol} | ${sig.side || 'HOLD'} | ${status}*`,
  ``,
  `💰 Price: \$${d.currentPrice}`,
  sig.side !== 'HOLD' ? [
    `📍 Entry: \$${sig.entryPrice}`,
    `🎯 TP:    \$${sig.tpPrice}`,
    `🛑 SL:    \$${sig.slPrice}`,
    `⚖️  R:R = ${pos.riskReward}x | Conf: ${Math.round((sig.confidence||0)*100)}%`
  ].join('\n') : '',
  ``,
  `📊 *Indicators*`,
  `RSI: ${d.rsi} | EMA align: ${d.ema_alignment}`,
  `MACD hist: ${d.macd?.histogram} | Pattern: ${d.pattern}`,
  ``,
  `📰 *News* (impact: ${d.newsAnalysis?.impactScore}/10)`,
  d.newsAnalysis?.summary || 'No summary',
  ``,
  `💬 *Sentiment*: ${d.sentiment?.label} (${d.sentiment?.score})`,
  ``,
  rm.approved ? [
    `🏦 *Position*`,
    `Qty: ${rm.finalQty} | Lev: ${rm.finalLeverage}x | Risk: \$${pos.riskUSD}`,
    `Kelly: ${pos.halfKelly}`
  ].join('\n') : `Reason: ${rm.reason || ''}`,
  ``,
  `⏱ ${new Date().toISOString().slice(0,19).replace('T',' ')} UTC`
].filter(l => l !== '').join('\n');

return [{ json: { message: lines, chatId: $env.TG_CHAT_IDS } }];
